import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_markdown/flutter_markdown.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
const gold=Color(0xFFC5A059),teal=Color(0xFF00D6C9),bg=Color(0xFF080A0D),panel=Color(0xFF151B22);
void main()=>runApp(const IraqAI());
class IraqAI extends StatelessWidget{const IraqAI({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'IRAQ AI',theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:bg,colorScheme:const ColorScheme.dark(primary:gold,secondary:teal,surface:panel)),home:const ChatPage());}
class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final input=TextEditingController(),scroll=ScrollController();final msgs=<Map<String,String>>[];String server='http://10.0.2.2:8000';String? cid;bool busy=false;
@override void initState(){super.initState();_load();}
Future<void> _load()async{final p=await SharedPreferences.getInstance();setState((){server=p.getString('server')??server;cid=p.getString('cid');final raw=p.getString('msgs');if(raw!=null){try{for(final x in jsonDecode(raw)){if(x is Map&&x['role']!=null&&x['content']!=null)msgs.add({'role':'${x['role']}','content':'${x['content']}'});}}catch(_){}}});}
Future<void> _save()async{final p=await SharedPreferences.getInstance();await p.setString('server',server);await p.setString('msgs',jsonEncode(msgs));if(cid!=null){await p.setString('cid',cid!);}else{await p.remove('cid');}}
Future<void> _settings()async{final c=TextEditingController(text:server);final v=await showDialog<String>(context:context,builder:(d)=>AlertDialog(title:const Text('عنوان خادم IRAQ AI'),content:TextField(controller:c,decoration:const InputDecoration(hintText:'http://192.168.1.5:8000')),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,c.text.trim()),child:const Text('حفظ'))]));c.dispose();if(v!=null&&Uri.tryParse(v)?.host.isNotEmpty==true){setState(()=>server=v.replaceFirst(RegExp(r'/+$'),''));await _save();}}
Future<void> _send()async{final t=input.text.trim();if(t.isEmpty||busy)return;setState((){msgs.add({'role':'user','content':t});busy=true;});input.clear();await _save();try{final r=await http.post(Uri.parse('$server/api/v1/chat'),headers:{'Content-Type':'application/json'},body:jsonEncode({'message':t,if(cid!=null)'conversation_id':cid})).timeout(const Duration(seconds:190));final data=jsonDecode(r.body);if(r.statusCode!=200)throw Exception(data['detail']??'HTTP ${r.statusCode}');setState((){cid=data['conversation_id'];msgs.add({'role':'assistant','content':data['answer']});});}catch(e){setState(()=>msgs.add({'role':'assistant','content':'تعذر الاتصال بالخادم: $e'}));}finally{setState(()=>busy=false);await _save();}}
@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('IRAQ AI – ذكاء العراق',style:TextStyle(color:gold,fontWeight:FontWeight.bold)),actions:[IconButton(onPressed:_settings,icon:const Icon(Icons.settings,color:teal)),IconButton(onPressed:busy?null:(){setState((){msgs.clear();cid=null;});_save();},icon:const Icon(Icons.add_comment,color:gold))]),body:Column(children:[Expanded(child:msgs.isEmpty?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.psychology_alt,color:teal,size:76),SizedBox(height:16),Text('مرحباً بك في ذكاء العراق',style:TextStyle(color:gold,fontSize:21,fontWeight:FontWeight.bold)),Text('اسأل، تعلّم، واكتشف')])):ListView.builder(controller:scroll,padding:const EdgeInsets.all(12),itemCount:msgs.length,itemBuilder:(c,i){final m=msgs[i],user=m['role']=='user';return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:720),margin:const EdgeInsets.symmetric(vertical:6),padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:user?const Color(0xFF123A39):panel,borderRadius:BorderRadius.circular(16),border:Border.all(color:user?teal.withOpacity(.4):gold.withOpacity(.25))),child:user?SelectableText(m['content']!):MarkdownBody(data:m['content']!,selectable:true)));})),if(busy)const LinearProgressIndicator(color:teal),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:input,minLines:1,maxLines:5,onSubmitted:(_)=>_send(),decoration:const InputDecoration(filled:true,fillColor:panel,hintText:'اكتب سؤالك هنا...',border:OutlineInputBorder()))),const SizedBox(width:8),IconButton.filled(onPressed:busy?_noop:_send,icon:const Icon(Icons.send))])))]));}
void _noop(){}@override void dispose(){input.dispose();scroll.dispose();super.dispose();}}
